&lt;tr&gt;
&lt;td&gt;Tokens (tabular data)&lt;/td&gt;
&lt;td&gt;100%&lt;/td&gt;
&lt;td&gt;~63%&lt;/td&gt;
&lt;td&gt;~72%&lt;/td&gt;
&lt;td&gt;~38%&lt;/td&gt;
&lt;td&gt;~40%&lt;/td&gt;
&lt;td&gt;~55%&lt;/td&gt;
&lt;/tr&gt;
